/* Consolidated Wingman style stack. Keep imported once from src/main.tsx. */

@tailwind base;
@tailwind components;
@tailwind utilities;

/* ==========================================================================
   Wingman UI Authority Layer
   Purpose: prevent page-by-page styling drift by forcing one shared shell,
   page host, card system, form treatment, colour palette and density scale.
   This block intentionally sits after Tailwind utilities so it wins.
   ========================================================================== */

:root {
  --wm-bg-0: #050b13;
  --wm-bg-1: #071522;
  --wm-bg-2: #0b2032;
  --wm-panel: rgba(10, 24, 38, 0.94);
  --wm-panel-soft: rgba(16, 36, 55, 0.82);
  --wm-surface: rgba(248, 251, 255, 0.98);
  --wm-surface-strong: #ffffff;
  --wm-surface-muted: #edf3fa;
  --wm-border-dark: rgba(255, 255, 255, 0.11);
  --wm-border-light: rgba(148, 163, 184, 0.34);
  --wm-text: #eef6ff;
  --wm-text-soft: #c6d4e6;
  --wm-text-muted: #8fa3ba;
  --wm-ink: #0d1724;
  --wm-ink-soft: #405063;
  --wm-ink-muted: #64748b;
  --wm-orange: #f6a340;
  --wm-orange-soft: rgba(246, 163, 64, 0.16);
  --wm-orange-border: rgba(246, 163, 64, 0.36);
  --wm-green: #22c55e;
  --wm-red: #ef4444;
  --wm-blue: #78a9ff;
  --wm-radius-lg: 18px;
  --wm-radius-xl: 22px;
  --wm-radius-2xl: 28px;
  --wm-sidebar-width: 268px;
  --wm-topbar-height: 64px;
  --wm-shadow-panel: 0 22px 70px rgba(0, 0, 0, 0.34);
  --wm-shadow-card: 0 18px 44px rgba(15, 23, 42, 0.12);
  --wm-font: Inter, ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
}

* {
  box-sizing: border-box;
}

html,
body,
#root {
  width: 100%;
  height: 100%;
  min-height: 100%;
  margin: 0;
  overflow: hidden;
}

body {
  font-family: var(--wm-font);
  color: var(--wm-text);
  background:
    radial-gradient(circle at top left, rgba(246, 163, 64, 0.13), transparent 28rem),
    radial-gradient(circle at bottom right, rgba(120, 169, 255, 0.13), transparent 30rem),
    linear-gradient(135deg, var(--wm-bg-0) 0%, var(--wm-bg-1) 44%, var(--wm-bg-2) 100%);
}

button,
input,
select,
textarea {
  font: inherit;
}

.wingman-shell {
  width: 100%;
  height: 100vh;
  min-height: 100vh;
  overflow: hidden;
  color: var(--wm-text);
  background:
    radial-gradient(circle at 82% 0%, rgba(246, 163, 64, 0.14), transparent 26rem),
    radial-gradient(circle at 18% 100%, rgba(120, 169, 255, 0.12), transparent 28rem),
    linear-gradient(145deg, var(--wm-bg-0) 0%, var(--wm-bg-1) 48%, var(--wm-bg-2) 100%);
}

.wingman-sidebar {
  position: fixed;
  inset: 0 auto 0 0;
  z-index: 60;
  width: var(--wm-sidebar-width);
  height: 100vh;
  overflow-y: auto;
  border-right: 1px solid var(--wm-border-dark);
  background:
    linear-gradient(180deg, rgba(9, 20, 33, 0.98) 0%, rgba(6, 14, 24, 0.98) 100%);
  box-shadow: 18px 0 48px rgba(0, 0, 0, 0.28);
  padding: 16px;
}

.wingman-workspace {
  height: 100vh;
  min-width: 0;
  margin-left: var(--wm-sidebar-width);
  display: grid;
  grid-template-rows: var(--wm-topbar-height) minmax(0, 1fr);
}

.wingman-topbar {
  position: sticky;
  top: 0;
  z-index: 45;
  min-width: 0;
  height: var(--wm-topbar-height);
  display: flex;
  align-items: center;
  gap: 14px;
  border-bottom: 1px solid var(--wm-border-dark);
  background:
    linear-gradient(90deg, rgba(7, 18, 31, 0.94), rgba(12, 31, 49, 0.88));
  backdrop-filter: blur(16px);
  padding: 0 22px;
}

.wingman-app-main {
  min-height: 0;
  overflow: auto;
  padding: 18px clamp(16px, 2vw, 28px) 28px;
  scroll-behavior: smooth;
}

.wingman-page-host {
  width: 100%;
  max-width: 1480px;
  margin: 0 auto;
}

.wingman-page-host > * {
  max-width: 100%;
}

.wingman-app-main::-webkit-scrollbar,
.wingman-sidebar::-webkit-scrollbar {
  width: 10px;
}

.wingman-app-main::-webkit-scrollbar-thumb,
.wingman-sidebar::-webkit-scrollbar-thumb {
  border: 2px solid transparent;
  border-radius: 999px;
  background: rgba(148, 163, 184, 0.34);
  background-clip: padding-box;
}

.wingman-brand {
  display: flex;
  align-items: center;
  gap: 12px;
  min-height: 66px;
  margin-bottom: 14px;
  padding: 12px;
  border: 1px solid var(--wm-border-dark);
  border-radius: var(--wm-radius-xl);
  background: rgba(255, 255, 255, 0.045);
}

.wingman-brand-mark {
  width: 42px;
  height: 42px;
  display: grid;
  place-items: center;
  border-radius: 16px;
  color: #1b1205;
  font-weight: 900;
  letter-spacing: -0.06em;
  background:
    radial-gradient(circle at 30% 20%, #ffe1a8, #f6a340 62%, #b85b0f);
  box-shadow: 0 0 30px rgba(246, 163, 64, 0.28);
}

.wingman-brand-copy {
  min-width: 0;
}

.wingman-brand-copy p {
  margin: 0;
  color: var(--wm-text-muted);
  font-size: 0.67rem;
  font-weight: 800;
  letter-spacing: 0.2em;
  text-transform: uppercase;
}

.wingman-brand-copy strong {
  display: block;
  margin-top: 2px;
  color: var(--wm-text);
  font-size: 1.15rem;
  letter-spacing: -0.03em;
}

.wingman-nav {
  display: grid;
  gap: 7px;
}

.wingman-nav-link {
  display: grid;
  grid-template-columns: 18px minmax(0, 1fr);
  align-items: center;
  gap: 11px;
  min-height: 48px;
  padding: 10px 11px;
  border: 1px solid transparent;
  border-radius: 16px;
  color: var(--wm-text-soft);
  text-decoration: none;
  transition:
    background 160ms ease,
    border-color 160ms ease,
    color 160ms ease,
    box-shadow 160ms ease,
    transform 160ms ease;
}

.wingman-nav-link:hover {
  transform: translateX(2px);
  border-color: var(--wm-border-dark);
  color: var(--wm-text);
  background: rgba(255, 255, 255, 0.055);
}

.wingman-nav-link-active {
  border-color: var(--wm-orange-border);
  color: #fff4e4;
  background:
    linear-gradient(135deg, rgba(246, 163, 64, 0.18), rgba(246, 163, 64, 0.08));
  box-shadow:
    inset 3px 0 0 var(--wm-orange),
    0 0 34px rgba(246, 163, 64, 0.16);
}

.wingman-nav-icon {
  width: 17px;
  height: 17px;
}

.wingman-nav-copy {
  min-width: 0;
  display: grid;
  gap: 2px;
}

.wingman-nav-copy span {
  overflow: hidden;
  font-size: 0.83rem;
  font-weight: 800;
  letter-spacing: -0.01em;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.wingman-nav-copy small {
  overflow: hidden;
  color: var(--wm-text-muted);
  font-size: 0.66rem;
  line-height: 1.25;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.wingman-topbar-title {
  min-width: 0;
  flex: 1;
}

.wingman-topbar-title p {
  margin: 0;
  color: var(--wm-text);
  font-size: 0.96rem;
  font-weight: 850;
  letter-spacing: -0.02em;
}

.wingman-topbar-title span {
  display: block;
  overflow: hidden;
  margin-top: 2px;
  color: var(--wm-text-muted);
  font-size: 0.76rem;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.wingman-mobile-nav-button,
.wingman-clear-project-button {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  border: 1px solid var(--wm-border-dark);
  border-radius: 999px;
  color: var(--wm-text);
  background: rgba(255, 255, 255, 0.055);
  transition:
    background 160ms ease,
    border-color 160ms ease,
    transform 160ms ease;
}

.wingman-mobile-nav-button {
  width: 42px;
  height: 42px;
}

.wingman-clear-project-button {
  gap: 8px;
  min-height: 38px;
  padding: 0 14px;
  color: #ffe9c9;
  font-size: 0.78rem;
  font-weight: 800;
}

.wingman-mobile-nav-button:hover,
.wingman-clear-project-button:hover {
  transform: translateY(-1px);
  border-color: var(--wm-orange-border);
  background: var(--wm-orange-soft);
}

.wingman-mobile-shade {
  display: none;
}

.wingman-panel {
  border: 1px solid var(--wm-border-dark) !important;
  background:
    radial-gradient(circle at 88% 0%, rgba(246, 163, 64, 0.13), transparent 18rem),
    linear-gradient(145deg, rgba(12, 31, 49, 0.96), rgba(8, 18, 30, 0.96)) !important;
  box-shadow: var(--wm-shadow-panel) !important;
  backdrop-filter: blur(12px);
}

.wingman-surface {
  color: var(--wm-ink) !important;
  border: 1px solid var(--wm-border-light) !important;
  background:
    linear-gradient(180deg, rgba(255, 255, 255, 0.99), rgba(242, 247, 252, 0.99)) !important;
  box-shadow: var(--wm-shadow-card) !important;
}

.wingman-grid {
  background-image:
    linear-gradient(rgba(255, 255, 255, 0.045) 1px, transparent 1px),
    linear-gradient(90deg, rgba(255, 255, 255, 0.045) 1px, transparent 1px);
  background-size: 26px 26px;
}

.wingman-kicker {
  margin: 0;
  color: var(--wm-text-muted) !important;
  font-size: 0.68rem !important;
  font-weight: 850 !important;
  letter-spacing: 0.18em !important;
  line-height: 1.2 !important;
  text-transform: uppercase !important;
}

.wingman-surface .wingman-kicker {
  color: #b45309 !important;
}

.wingman-display {
  margin: 0;
  font-family: var(--wm-font) !important;
  font-weight: 850 !important;
  letter-spacing: -0.055em !important;
}

.wingman-page-hero {
  display: grid;
  gap: 18px;
  margin-bottom: 18px;
  padding: clamp(22px, 2.4vw, 34px);
  border-radius: var(--wm-radius-2xl);
}

.wingman-hero-copy {
  max-width: 1040px;
}

.wingman-hero-copy .wingman-display {
  margin-top: 8px;
  max-width: 980px;
  color: var(--wm-text);
  font-size: clamp(2rem, 4vw, 4.25rem);
  line-height: 0.94;
}

.wingman-hero-purpose {
  max-width: 900px;
  margin: 12px 0 0;
  color: var(--wm-text-soft);
  font-size: clamp(0.92rem, 1vw, 1.04rem);
  line-height: 1.62;
}

.wingman-hero-next {
  display: grid;
  gap: 5px;
  max-width: 980px;
  padding: 13px 15px;
  border: 1px solid var(--wm-border-dark);
  border-radius: var(--wm-radius-lg);
  background: rgba(255, 255, 255, 0.055);
}

.wingman-hero-next span {
  color: var(--wm-orange);
  font-size: 0.67rem;
  font-weight: 900;
  letter-spacing: 0.18em;
  text-transform: uppercase;
}

.wingman-hero-next p {
  margin: 0;
  color: var(--wm-text);
  font-size: 0.9rem;
  line-height: 1.5;
}

.wingman-hero-actions {
  display: flex;
  flex-wrap: wrap;
  gap: 10px;
}

.wingman-hero-action {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  min-height: 38px;
  border-radius: 999px;
  padding: 0 15px;
  font-size: 0.84rem;
  font-weight: 850;
  text-decoration: none;
  transition:
    transform 160ms ease,
    background 160ms ease,
    border-color 160ms ease,
    box-shadow 160ms ease;
}

.wingman-hero-action:hover {
  transform: translateY(-1px);
}

.wingman-hero-action-primary {
  border: 1px solid rgba(255, 216, 160, 0.38);
  color: #1a1208;
  background: linear-gradient(135deg, #ffc36a, var(--wm-orange));
  box-shadow: 0 14px 32px rgba(246, 163, 64, 0.24);
}

.wingman-hero-action-secondary {
  border: 1px solid var(--wm-border-dark);
  color: var(--wm-text);
  background: rgba(255, 255, 255, 0.06);
}

.wingman-section-card {
  overflow: hidden;
  border-radius: var(--wm-radius-2xl);
}

.wingman-section-card-header {
  display: flex;
  align-items: flex-end;
  justify-content: space-between;
  gap: 16px;
  padding: 18px 20px 15px;
  border-bottom: 1px solid rgba(148, 163, 184, 0.28);
}

.wingman-section-card-header h2 {
  margin: 4px 0 0;
  color: var(--wm-ink);
  font-size: clamp(1.2rem, 1.6vw, 1.65rem);
  font-weight: 850;
  letter-spacing: -0.035em;
}

.wingman-section-card-header p:not(.wingman-kicker) {
  max-width: 760px;
  margin: 6px 0 0;
  color: var(--wm-ink-muted);
  font-size: 0.88rem;
  line-height: 1.55;
}

.wingman-section-card-actions {
  flex-shrink: 0;
}

.wingman-section-card-body {
  padding: 18px 20px 20px;
}

.wingman-page-host :where(.rounded-3xl) {
  border-radius: var(--wm-radius-2xl) !important;
}

.wingman-page-host :where(.rounded-2xl) {
  border-radius: var(--wm-radius-lg) !important;
}

.wingman-page-host :where(.p-8, .lg\:p-8, .lg\:p-10) {
  padding: 22px !important;
}

.wingman-page-host :where(.gap-6) {
  gap: 18px !important;
}

.wingman-page-host :where(.mb-8) {
  margin-bottom: 18px !important;
}

.wingman-page-host :where(.space-y-6 > :not([hidden]) ~ :not([hidden])) {
  margin-top: 18px !important;
}

.wingman-page-host :where(.wm-dark-blue-sanitised-selector, .wm-dark-blue-sanitised-selector, .wm-dark-blue-sanitised-selector) {
  background: var(--wm-surface-strong) !important;
}

.wingman-page-host :where(.wm-dark-blue-sanitised-selector, .wm-dark-blue-sanitised-selector) {
  background: var(--wm-surface-muted) !important;
}

.wingman-page-host :where(.wm-dark-blue-sanitised-selector, .wm-dark-blue-sanitised-selector) {
  border-color: rgba(148, 163, 184, 0.3) !important;
}

.wingman-page-host :where(.wm-dark-blue-sanitised-selector, .wm-dark-blue-sanitised-selector) {
  color: var(--wm-ink) !important;
}

.wingman-page-host :where(.text-slate-600, .text-gray-600) {
  color: var(--wm-ink-soft) !important;
}

.wingman-page-host :where(.text-slate-500, .text-gray-500) {
  color: var(--wm-ink-muted) !important;
}

.wingman-panel :where(.wm-dark-blue-sanitised-selector, .wm-dark-blue-sanitised-selector, .wm-dark-blue-sanitised-selector, .wm-dark-blue-sanitised-selector) {
  color: var(--wm-text) !important;
}

.wingman-panel :where(.text-slate-600, .text-gray-600, .text-slate-500, .text-gray-500, .text-slate-400) {
  color: var(--wm-text-muted) !important;
}

.wingman-page-host :where(input, select, textarea) {
  min-height: 38px;
  border: 1px solid rgba(148, 163, 184, 0.42) !important;
  border-radius: 14px !important;
  color: var(--wm-ink) !important;
  background: rgba(255, 255, 255, 0.98) !important;
  outline: none;
  box-shadow: inset 0 1px 0 rgba(15, 23, 42, 0.04);
}

.wingman-page-host :where(input, select, textarea):focus {
  border-color: rgba(246, 163, 64, 0.68) !important;
  box-shadow:
    0 0 0 3px rgba(246, 163, 64, 0.14),
    inset 0 1px 0 rgba(15, 23, 42, 0.04);
}

.wingman-panel :where(input, select, textarea) {
  color: var(--wm-text) !important;
  border-color: var(--wm-border-dark) !important;
  background: rgba(255, 255, 255, 0.08) !important;
}

.wingman-page-host :where(button, a) {
  text-underline-offset: 3px;
}

.wingman-page-host :where(table) {
  width: 100%;
  border-collapse: separate;
  border-spacing: 0;
  overflow: hidden;
  border: 1px solid rgba(148, 163, 184, 0.28);
  border-radius: var(--wm-radius-lg);
}

.wingman-page-host :where(th) {
  color: var(--wm-ink);
  background: rgba(226, 232, 240, 0.72);
  font-size: 0.76rem;
  font-weight: 850;
  letter-spacing: 0.08em;
  text-transform: uppercase;
}

.wingman-page-host :where(td, th) {
  border-bottom: 1px solid rgba(148, 163, 184, 0.22);
  padding: 10px 12px;
}

.wingman-page-host :where(.text-orange-600, .text-orange-500, .text-amber-600, .text-amber-500) {
  color: #b45309 !important;
}

.wingman-page-host :where(.bg-orange-400, .bg-orange-500, .bg-amber-400, .bg-amber-500) {
  background: linear-gradient(135deg, #ffc36a, var(--wm-orange)) !important;
}

.wingman-page-host :where(.shadow-\[0_10px_30px_rgba\(251\,146\,60\,0\.12\)\]) {
  box-shadow: 0 14px 38px rgba(246, 163, 64, 0.18) !important;
}

@media (min-width: 1024px) {
  .wingman-mobile-nav-button {
    display: none;
  }
}

@media (max-width: 1023px) {
  html,
  body,
  #root {
    overflow: hidden;
  }

  .wingman-sidebar {
    transform: translateX(-105%);
    transition: transform 200ms ease;
  }

  .wingman-sidebar[data-mobile-open="true"] {
    transform: translateX(0);
  }

  .wingman-mobile-shade {
    position: fixed;
    inset: 0;
    z-index: 50;
    display: block;
    pointer-events: none;
    background: rgba(0, 0, 0, 0);
    transition: background 200ms ease;
  }

  .wingman-mobile-shade[data-mobile-open="true"] {
    pointer-events: auto;
    background: rgba(0, 0, 0, 0.48);
  }

  .wingman-workspace {
    margin-left: 0;
  }

  .wingman-topbar {
    padding: 0 12px;
  }

  .wingman-clear-project-button {
    min-width: 38px;
    width: 38px;
    padding: 0;
  }

  .wingman-clear-project-button svg {
    margin: 0;
  }

  .wingman-clear-project-button {
    font-size: 0;
  }

  .wingman-app-main {
    padding: 14px 12px 22px;
  }

  .wingman-page-hero {
    padding: 20px;
  }

  .wingman-section-card-header,
  .wingman-section-card-body {
    padding-left: 16px;
    padding-right: 16px;
  }
}

@media (max-width: 720px) {
  .wingman-topbar-title span {
    display: none;
  }

  .wingman-section-card-header {
    align-items: flex-start;
    flex-direction: column;
  }
}
