/* WINGMAN-TEMPLATE-DYNAMIC-SCALING-CARDS-START */
/*
  Dynamic scaling rules for /wingman/templates.

  Goal:
  - Cards scale to available page width.
  - No fixed 2/3-column forcing.
  - No horizontal card layout unless the card is genuinely wide enough.
  - Card text remains readable.
  - Many templates scroll vertically.
  - Few templates still look like proper buttons/cards.
*/

/* Page shell */
.wm-templates-workflow-page {
  height: calc(100vh - var(--wm-topbar-height) - 24px) !important;
  min-height: 0 !important;
  overflow: hidden !important;
}

.wm-templates-workflow-page .wingman-section-card,
.wm-templates-workflow-page .wingman-section-card-body,
.wm-templates-workflow-page .wm-template-results-panel,
.wm-templates-workflow-page .wm-template-step-panel {
  min-height: 0 !important;
}

/* --------------------------------------------------------------------------
   Step 1: application selector buttons
   -------------------------------------------------------------------------- */

.wm-templates-workflow-page[data-template-step="choose"] .wm-template-market-grid {
  min-height: 0 !important;
  display: grid !important;
  grid-template-columns: repeat(auto-fit, minmax(min(100%, 430px), 1fr)) !important;
  gap: clamp(14px, 1.2vw, 22px) !important;
  align-content: start !important;
  align-items: stretch !important;
}

.wm-templates-workflow-page[data-template-step="choose"] .wm-template-market-card {
  min-height: clamp(140px, 14vh, 190px) !important;
  display: grid !important;
  grid-template-columns: clamp(130px, 28%, 190px) minmax(0, 1fr) !important;
  overflow: hidden !important;
  border: 1px solid rgba(148, 163, 184, 0.34) !important;
  border-radius: 24px !important;
  background: #ffffff !important;
  box-shadow: 0 16px 36px rgba(15, 23, 42, 0.12) !important;
  text-align: left !important;
}

.wm-templates-workflow-page[data-template-step="choose"] .wm-template-market-image {
  width: 100% !important;
  height: 100% !important;
  min-height: clamp(140px, 14vh, 190px) !important;
  background-size: cover !important;
  background-position: center !important;
}

.wm-templates-workflow-page[data-template-step="choose"] .wm-template-market-label {
  min-width: 0 !important;
  display: grid !important;
  grid-template-columns: auto minmax(0, 1fr) auto !important;
  align-items: center !important;
  gap: clamp(10px, 1vw, 14px) !important;
  padding: clamp(14px, 1.3vw, 22px) !important;
  color: #0f172a !important;
  background: linear-gradient(180deg, #ffffff 0%, #f8fafc 100%) !important;
}

.wm-templates-workflow-page[data-template-step="choose"] .wm-template-market-label > div {
  min-width: 0 !important;
  overflow: visible !important;
}

.wm-templates-workflow-page[data-template-step="choose"] .wm-template-market-label strong {
  display: block !important;
  color: #0f172a !important;
  font-size: clamp(0.98rem, 1.05vw, 1.18rem) !important;
  line-height: 1.15 !important;
  font-weight: 850 !important;
  white-space: normal !important;
  overflow: visible !important;
  text-overflow: clip !important;
}

.wm-templates-workflow-page[data-template-step="choose"] .wm-template-market-label span {
  display: block !important;
  margin-top: 7px !important;
  color: #475569 !important;
  font-size: clamp(0.78rem, 0.8vw, 0.9rem) !important;
  line-height: 1.35 !important;
  font-weight: 600 !important;
  white-space: normal !important;
  overflow: visible !important;
  text-overflow: clip !important;
}

.wm-templates-workflow-page[data-template-step="choose"] .wm-template-market-label small {
  min-width: 36px !important;
  height: 36px !important;
  display: inline-grid !important;
  place-items: center !important;
  border-radius: 999px !important;
  color: #0f172a !important;
  background: #e2e8f0 !important;
  font-size: 0.8rem !important;
  font-weight: 850 !important;
}

/* --------------------------------------------------------------------------
   Step 2: template result cards
   -------------------------------------------------------------------------- */

.wm-templates-workflow-page[data-template-step="results"] .wm-template-room-scroll-grid {
  height: 100% !important;
  min-height: 0 !important;
  overflow-y: auto !important;
  display: grid !important;
  grid-template-columns: repeat(auto-fit, minmax(min(100%, 390px), 1fr)) !important;
  grid-auto-rows: auto !important;
  gap: clamp(16px, 1.25vw, 22px) !important;
  align-content: start !important;
  align-items: stretch !important;
  padding: 6px 12px 18px 4px !important;
}

