}

.wm-templates-workflow-page[data-template-step="results"] .wm-template-room-meta {
  align-self: end !important;
  display: flex !important;
  flex-wrap: wrap !important;
  gap: 7px !important;
}

.wm-templates-workflow-page[data-template-step="results"] .wm-template-room-meta span {
  min-height: 28px !important;
  display: inline-flex !important;
