/* WINGMAN-GLOBAL-SCROLL-SAFETY-START */
/*
  Global layout repair:
  - Keep the app shell fixed.
  - Keep the sidebar/topbar stable.
  - Make the main workspace the reliable vertical scroll container.
  - Stop page-level fixed-height/overflow rules from clipping content.
*/

html,
body,
#root {
  width: 100% !important;
  height: 100% !important;
  min-height: 100% !important;
  overflow: hidden !important;
}

.wingman-shell {
  width: 100% !important;
  height: 100vh !important;
  min-height: 100vh !important;
  overflow: hidden !important;
}

.wingman-workspace {
  height: 100vh !important;
  min-height: 0 !important;
  display: grid !important;
  grid-template-rows: var(--wm-topbar-height) minmax(0, 1fr) !important;
  overflow: hidden !important;
}

.wingman-app-main {
  min-height: 0 !important;
  height: auto !important;
  overflow-x: hidden !important;
  overflow-y: auto !important;
  overscroll-behavior: contain !important;
  -webkit-overflow-scrolling: touch !important;
  padding-bottom: 72px !important;
}

.wingman-page-host {
  min-height: 100% !important;
  height: auto !important;
  overflow: visible !important;
  padding-bottom: 32px !important;
}

.wingman-page-host > * {
  height: auto !important;
  max-height: none !important;
}

/*
  Page root safety.
  Many Wingman pages were designed as fixed panels. That can clip content when
  the browser height is smaller than the page content. These rules allow the
  main scroll container to reveal the full page.
*/

.wm-simple-discovery-page,
.wm-intel-page,
.wm-profile-page,
.wm-template-page,
.wm-templates-page,
.wm-product-finder-page,
.wm-product-family-page,
.wm-product-pitch-page,
.wm-callcards-page,
.wm-call-card-page,
.wm-sales-helper-page,
.wm-videowall-page,
.wm-proposal-page,
.wm-support-page,
.wm-ingest-page,
.wm-projects-page,
[class*="Page"],
[class*="-page"] {
  height: auto !important;
  max-height: none !important;
  overflow: visible !important;
}

/*
  Known fixed-height Wingman panel systems.
  Allow these to grow and let .wingman-app-main do the scrolling.
*/

.wm-simple-discovery-shell,
.wm-simple-discovery-body,
.wm-simple-discovery-main,
.wm-simple-step,
.wm-simple-model-panel,
.wm-intel-workspace,
.wm-intel-record-list,
.wm-intel-editor,
.wm-intel-panel,
.wm-profile-grid,
.wm-template-workspace,
.wm-template-results,
.wm-finder-workspace,
.wm-finder-results,
.wm-product-finder-shell,
.wm-product-finder-results,
.wm-callcard-workspace,
.wm-proposal-workspace {
  height: auto !important;
  max-height: none !important;
  min-height: 0 !important;
  overflow: visible !important;
}

/*
  Preserve horizontal overflow only where needed for tables/navigation.
*/

.wm-intel-tabs,
.wm-simple-discovery-steps,
.wingman-nav,
table,
.wm-table-scroll {
  max-width: 100% !important;
}

table {
  overflow-x: auto !important;
}

/*
  Sidebar remains independently scrollable because navigation can exceed height.
*/

.wingman-sidebar {
  overflow-x: hidden !important;
  overflow-y: auto !important;
  overscroll-behavior: contain !important;
}

/*
  Mobile/tablet fallback: allow natural page flow.
*/

@media (max-width: 1180px) {
  .wingman-shell,
  .wingman-workspace {
    min-height: 100vh !important;
  }

  .wingman-app-main {
    overflow-y: auto !important;
  }

  .wingman-page-host,
  .wingman-page-host > *,
  [class*="-page"],
  [class*="Page"] {
    height: auto !important;
    max-height: none !important;
    overflow: visible !important;
  }
}
/* WINGMAN-GLOBAL-SCROLL-SAFETY-END */

