.wm-profile-evidence-card {
  display: grid !important;
  grid-template-columns: minmax(0, 1.1fr) minmax(280px, 0.9fr) !important;
  gap: 14px !important;
  border: 1px solid rgba(14, 165, 233, 0.22) !important;
  border-radius: 20px !important;
  background: #f0f9ff !important;
  padding: 16px !important;
}

.wm-profile-evidence-card h3 {
  margin: 4px 0 0 !important;
  color: #0f172a !important;
  font-size: 1.2rem !important;
  line-height: 1.15 !important;
  font-weight: 900 !important;
}

.wm-profile-evidence-card span {
  display: block !important;
  margin-top: 6px !important;
  color: #334155 !important;
  font-size: 0.86rem !important;
  line-height: 1.45 !important;
}

.wm-profile-evidence-card dl {
  display: grid !important;
  gap: 8px !important;
  margin: 0 !important;
}

.wm-profile-evidence-card dl div {
  border: 1px solid rgba(14, 165, 233, 0.18) !important;
  border-radius: 14px !important;
  background: #ffffff !important;
  padding: 10px !important;
}

.wm-profile-evidence-card dt {
  margin: 0 !important;
  color: #0369a1 !important;
  font-size: 0.66rem !important;
  font-weight: 900 !important;
  letter-spacing: 0.11em !important;
  text-transform: uppercase !important;
}

.wm-profile-evidence-card dd {
  margin: 4px 0 0 !important;
  color: #0f172a !important;
  font-size: 0.82rem !important;
  line-height: 1.35 !important;
  font-weight: 750 !important;
}

.wm-feature-audit[open] {
  border-color: rgba(34, 197, 94, 0.24) !important;
}

.wm-feature-audit-table {
  display: grid !important;
  gap: 8px !important;
  margin-top: 12px !important;
}

.wm-feature-audit-row {
  display: grid !important;
  grid-template-columns: minmax(220px, 1.1fr) minmax(120px, 0.45fr) minmax(120px, 0.45fr) !important;
  gap: 10px !important;
  align-items: stretch !important;
