    "icon note" !important;
  gap: 2px 8px !important;
  align-items: start !important;
}

.wm-feature-audit-icon {
  grid-area: icon !important;
  width: 24px !important;
  height: 24px !important;
  display: inline-grid !important;
  place-items: center !important;
  border-radius: 999px !important;
  font-size: 0.95rem !important;
  font-weight: 900 !important;
}

.wm-feature-audit-row.is-match .wm-feature-audit-icon,
.wm-feature-audit-row.is-better .wm-feature-audit-icon {
  background: #dcfce7 !important;
  color: #15803d !important;
}

.wm-feature-audit-row.is-gap .wm-feature-audit-icon {
  background: #fee2e2 !important;
  color: #b91c1c !important;
}

.wm-feature-audit-row.is-verify .wm-feature-audit-icon {
  background: #fef3c7 !important;
  color: #92400e !important;
}

.wm-feature-audit-row strong {
  grid-area: title !important;
  color: #0f172a !important;
  font-size: 0.84rem !important;
  line-height: 1.2 !important;
  font-weight: 900 !important;
}

.wm-feature-audit-row small {
  grid-area: note !important;
  color: #64748b !important;
  font-size: 0.72rem !important;
  line-height: 1.35 !important;
}

