/* WINGMAN DARK READABILITY SYSTEM END */

/* WINGMAN MERGED GLOBAL UNIFORMITY START */

/* ==========================================================================
   WINGMAN GLOBAL UNIFORMITY LAYER
   Imported last from src/main.tsx.

   Purpose:
   Reduce page-to-page visual drift while local TSX/Tailwind styling is
   gradually replaced with semantic Wingman classes.
   ========================================================================== */

:root {
  --wm-uniform-bg-0: #020817;
  --wm-uniform-bg-1: #061527;
  --wm-uniform-panel: rgba(7, 23, 42, 0.86);
  --wm-uniform-panel-strong: rgba(8, 31, 54, 0.94);
  --wm-uniform-border: rgba(103, 232, 249, 0.26);
  --wm-uniform-border-strong: rgba(103, 232, 249, 0.46);
  --wm-uniform-title: #67e8f9;
  --wm-uniform-title-soft: #a5f3fc;
  --wm-uniform-text: #ffffff;
  --wm-uniform-muted: rgba(226, 242, 255, 0.76);
  --wm-uniform-faint: rgba(226, 242, 255, 0.56);
  --wm-uniform-radius: 24px;
  --wm-uniform-radius-small: 14px;
  --wm-uniform-shadow: 0 18px 60px rgba(0, 0, 0, 0.34);
  --wm-uniform-glow: 0 0 0 1px rgba(103, 232, 249, 0.12), 0 18px 60px rgba(8, 145, 178, 0.14);
}

/* App background */

html,
body,
#root {
  min-height: 100%;
  background:
    radial-gradient(circle at 20% 0%, rgba(34, 211, 238, 0.13), transparent 34%),
    radial-gradient(circle at 86% 8%, rgba(20, 184, 166, 0.10), transparent 30%),
    linear-gradient(135deg, var(--wm-uniform-bg-0), var(--wm-uniform-bg-1) 58%, #020617) !important;
  color: var(--wm-uniform-text) !important;
}

body,
main {
  color: var(--wm-uniform-text) !important;
}

/* Headings */

main h1,
main h2,
main h3,
main .wm-page-title,
main .wm-section-title,
main .wm-card-title,
main [class*="page-title"],
main [class*="section-title"],
main [class*="card-title"],
main [class*="heading"] {
  color: var(--wm-uniform-title) !important;
}

main h4,
main h5,
main h6 {
  color: var(--wm-uniform-title-soft) !important;
}

/* Text */

main p,
main li,
main label {
  color: var(--wm-uniform-text) !important;
}

main small,
main .wm-muted-text,
main [class*="muted"],
main [class*="subtitle"],
main [class*="description"],
main [class*="helper"],
main [class*="hint"] {
  color: var(--wm-uniform-muted) !important;
}

main [class*="text-slate-"],
main [class*="text-gray-"],
main [class*="text-zinc-"],
main [class*="text-neutral-"],
main [class*="text-stone-"] {
  color: var(--wm-uniform-muted) !important;
}

main h1[class*="text-"],
main h2[class*="text-"],
main h3[class*="text-"],
main [class*="title"][class*="text-"] {
  color: var(--wm-uniform-title) !important;
}

/* Shared Wingman surfaces */

.wm-page,
.wm-page-shell,
.wm-page-frame,
.wm-workspace,
.wm-route-page {
  background: transparent !important;
  color: var(--wm-uniform-text) !important;
}

.wm-panel,
.wm-card,
.wm-section,
.wm-section-card,
.wm-action-card,
.wm-choice-card,
.wm-page-header,
.wm-page-hero,
.wm-ai-rail,
.wm-guru-panel,
.wm-product-card,
.wm-project-card,
.wm-template-card,
.wm-call-card,
.wm-comparison-card,
.wm-discovery-card,
.wm-finder-card,
.wm-proposal-card {
  background:
    linear-gradient(145deg, rgba(8, 31, 54, 0.94), rgba(6, 21, 39, 0.84)) !important;
  border: 1px solid var(--wm-uniform-border) !important;
  border-radius: var(--wm-uniform-radius) !important;
  box-shadow: var(--wm-uniform-glow) !important;
  color: var(--wm-uniform-text) !important;
}

/* Common Tailwind-style cards still inside pages */

main [class*="rounded-2xl"][class*="border"],
main [class*="rounded-3xl"][class*="border"],
main [class*="rounded-xl"][class*="border"] {
  background:
    linear-gradient(145deg, rgba(8, 31, 54, 0.94), rgba(6, 21, 39, 0.84)) !important;
  border-color: var(--wm-uniform-border) !important;
  color: var(--wm-uniform-text) !important;
  box-shadow: var(--wm-uniform-glow) !important;
}

/* Borders */

main [class*="border-white"],
main [class*="border-slate-"],
main [class*="border-gray-"],
main [class*="border-zinc-"],
main [class*="border-cyan-"],
main [class*="border-sky-"],
main [class*="border-blue-"],
main [class*="border-teal-"] {
  border-color: var(--wm-uniform-border) !important;
}

main hr {
  border-color: var(--wm-uniform-border) !important;
}

/* Buttons */

main button,
main a[class*="button"],
main a[class*="btn"],
main .wm-primary-action,
main .wm-secondary-action,
main .wm-action-button {
  border-radius: 999px !important;
  border-color: var(--wm-uniform-border-strong) !important;
  color: #ffffff !important;
}

main .wm-primary-action,
main button[class*="primary"],
main a[class*="primary"] {
  background: linear-gradient(135deg, rgba(8, 145, 178, 0.94), rgba(20, 184, 166, 0.88)) !important;
  color: #ffffff !important;
}

main .wm-secondary-action,
main a[class*="secondary"] {
  background: rgba(8, 31, 54, 0.74) !important;
  color: #ffffff !important;
}

main button:hover,
main a:hover {
  border-color: rgba(103, 232, 249, 0.72) !important;
}

/* Forms */

main input,
main select,
main textarea {
  background: rgba(2, 8, 23, 0.74) !important;
  border: 1px solid var(--wm-uniform-border) !important;
  border-radius: var(--wm-uniform-radius-small) !important;
  color: #ffffff !important;
}

main input::placeholder,
main textarea::placeholder {
  color: var(--wm-uniform-faint) !important;
}

main input:focus,
main select:focus,
main textarea:focus {
  border-color: rgba(103, 232, 249, 0.78) !important;
  outline: 2px solid rgba(103, 232, 249, 0.18) !important;
  outline-offset: 2px !important;
}

/* Pills, chips and badges */

main .wm-status-pill,
main .wm-chip,
main [class*="pill"],
main [class*="chip"],
main [class*="badge"] {
  border: 1px solid var(--wm-uniform-border) !important;
  background: rgba(8, 31, 54, 0.76) !important;
  color: var(--wm-uniform-title-soft) !important;
  border-radius: 999px !important;
}

/* Reduce oversized page hero dominance */

main .wm-page-hero,
main .wm-page-header,
main [class*="hero"],
main [class*="Hero"] {
  padding-block: clamp(1rem, 2vw, 1.75rem) !important;
  margin-bottom: 1rem !important;
}

/* Preserve warning/error visibility */

main [class*="danger"],
main [class*="error"],
main [class*="destructive"],
main [class*="text-red-"] {
  color: #fca5a5 !important;
}

/* ==========================================================================
